+proc test {name code okpattern} {
+    puts -nonewline [format "%-70s " $name]
+    flush stdout
+    set retval [uplevel 1 $code]
+    if {$okpattern eq $retval || [string match $okpattern $retval]} {
+        puts "PASSED"
+        incr ::passed
