+proc redis_bulk_read fd {
+    set count [redis_read_integer $fd]
+    if {$count eq {nil}} return {}
+    set len [expr {abs($count)}]
+    set buf [redis_readnl $fd $len]
+    if {$count < 0} {return "***ERROR*** $buf"}
+    return $buf
