+
+proc redis_multi_bulk_read fd {
+    set count [redis_read_integer $fd]
+    if {$count eq {nil}} return {}
+    if {$count < 0} {
+        set len [expr {abs($count)}]
+        set buf [redis_readnl $fd $len]
+        return "***ERROR*** $buf"
+    }
+    set l {}
+    for {set i 0} {$i < $count} {incr i} {
+        lappend l [redis_bulk_read $fd]
+    }
+    return $l
+}
